    show: 0,                                       // kiểu mặc định: trắng
    spoke: 1.5, rim: 2.2, ring: 1.2, cable: 0.35, hub: 0.6,   // độ sáng 32 thanh chính, viền vành chính, vành phụ/vành moay-ơ, cáp chéo, moay-ơ (ước lượng)
