  },
  /* ---- Tour (GĐ7): điểm 4 lên cabin, tua nhanh tới đỉnh rồi giảm tốc; điểm 5 ngắm 4 cầu từ đỉnh; điểm 6 show LED đêm. Không thêm mesh/đèn ---- */
  tour: {
